 "topic":"فیکشن کی اقسام",
 "affirmation":"آپ نے ماڈلز اور روزمرہ مثال سے فیکشن کا ربط واضح کیا۔",
 "identity":"آپ نے ہر مرحلے میں visual models (سرکل، ریکٹینگل، اسکوائر) استعمال کیا اور بچوں کو بولنے کے لیے مسلسل بلایا، جس نے سبق کو محسوساتی اور مربوط بنایا۔ آپ نے چھوٹی روزمرہ مثالیں (کیك، برابر حصے) استعمال کر کے کنسپٹ کو بچوں کی روزمرہ دنیا سے جوڑا۔",
 "moments":[
  {
   "title":"Opening Model Question",
   "quote":"یہ کیا چیز ہے؟ یہ ایک ماڈل ہے، ٹھیک ہے؟ یہ کیا ہے؟",
   "why":"آپ نے ماڈل دکھا کر یہ سوال پوچھا، جس نے بچوں کو پہلے شکل پہ پہچان اور پھر پارٹس گننے کی طرف سوچنے پر لایا۔"
  },
  {
   "title":"Notation Clarification Moment",
   "quote":"ٹھیک ہے، 9 ہم نے اوپر لکھنا ہے، اور 10؟",
   "why":"آپ نے طالبِ علم کے جملے کو اٹھایا اور اوپر/نیچے لکھنے کی جگہ واضح کی، جس سے notation کی فوری درستی ہوئی۔"
  },
  {
   "title":"Cake Example Anchor",
   "quote":"پارٹ اس لیے لاتے ہیں اور ایکول پارٹ لاتے ہیں تاکہ اس میں لائن نہ آئے۔",
   "why":"آپ نے کیک کی مثال دی، جس نے مساوات اور عملی معنی (فائرنس) بچوں کے ذہن میں لانے اور کلاس کی دلچسپی بڑھانے میں مدد دی۔"
  }
 ],
 "strength_name":"Concrete models",
 "strength_note":"آپ نے سرکل، ریکٹینگل اور حقیقی مثال (کیك) دکھا کر تصورات کو قابلِ محسوس بنایا اور بچوں کی شرکت بڑھائی۔",
 "horizon_title":"Tiered Tasks",
 "horizon_note":"آپ نے اس سبق میں سب طلبہ کو ایک ہی کام دیا — اگلا افق 'Tiered Tasks' میں سادہ اور تھوڑا مشکل دونوں سطح کے سوالات کلاس میں شامل کرنا ہوگا تاکہ ہر طالبِ علم مناسب سطح پر مشق کرے۔",
 "journey_note":"آپ نے اس ایک نشست میں واضح شروعات کی اور مخصوص ماڈلز سے سبق کو 75% تک پہنچایا، یہی تکرار مستقبل میں مزید مضبوطی لائے گی۔",
 "score_framing":"75% ایک عبوری سنگِ میل تھا، جو دکھاتا ہے کہ بنیاد مضبوط ہے اور اگلے چھوٹے قدم بڑے فرق لا سکتے ہیں۔",
 "domain_whys":{
  "high_leverage_practices":"یہ اسکور بہتر ہے کیونکہ آپ نے ماڈل دکھا کر 'یہ کیا چیز ہے؟' جیسے سوالات پوچھے اور بچوں سے فوری جوابات لیے — مکمل نمبر اس لیے نہیں کیونکہ آپ نے ہر طالبِ علم کے جواب کی وجہ پوچھ کر ان کی reasoning میں گہرائی نہیں لائی۔",
  "student_engagement":"یہ اسکور اچھا ہے کیونکہ آپ نے ماڈلز اور کیک کی مثال استعمال کی اور طلبہ نے مختلف انداز سے جواب دیا ('یہ سرکل ہے.' اور 'جو کلر کیا ہوا ہے، وہ اوپر ہے') — مکمل نمبر اس لیے نہیں کیونکہ طلبہ کے آنے والے سوالات زیادہ تر procedural تھے (مثلاً 'ٹیسٹ لکھیں؟' یا 'اس کا سائز ہوگا؟')، جو موضوعی سمجھ کے سوالات نہیں تھے۔",
  "teacher_subject_knowledge":"یہ اسکور بہتر ہے کیونکہ آپ نے ماڈلز اور نوٹیشن کے ذریعے fra ction کی وضاحت کی اور '9 ہم نے اوپر لکھنا ہے، اور 10؟' جیسا فقرہ استعمال کر کے فوری درستی کی — مکمل نمبر اس لیے نہیں کیونکہ آپ نے اس سبق میں کئی مرحلوں والے مسائل یا سوچنے کا وقفہ فراہم نہیں کیا اور عام misconceptions کو واضح طور پر بطور طالبِ علم کی رائے کے طور پر بیان نہیں کیا۔"
 }
